async function processRequest(input) {
  console.log("waiting");
  await new Promise(resolve => setTimeout(resolve, input.var.waitingTime));

  try {
    const resp = await fetch(`http://localhost:3001/next/${input.runId}`, { method: 'GET' });
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const data = await resp.json().catch(()=>null);
    return { status: 'done', response: data };
  } catch (err) {
    console.error('fetch failed', err);
    return { status: 'error', error: String(err) };
  }
}

